			return -1
		}
		if ch == '"' {
			if offset+2 < len(text) && text[offset:offset+3] == "\"\"\"" {
				return -1
			}
			for offset++; offset < len(text) && text[offset] != '"'; offset++ {
				if text[offset] == '\n' || text[offset] == '\r' {
					return -1
				}
				if text[offset] == '\\' {
					offset++
				}
			}
			if offset >= len(text) {
				return -1
			}
			continue
		}
		if ch == '(' {
			depth++
		} else if ch == ')' {
